args.command:
cd ~/captures; python3 -c "
from PIL import Image
for f in ['wrist_003.png','wrist_004.png','wrist_005.png']:
    im=Image.open(f).convert('L'); w,h=im.size; px=im.load()
    pts=[(x,y) for y in range(380,h) for x in range(w) if px[x,y]<60]
    if pts: print(f, sum(p[0] for p in pts)/len(pts), sum(p[1] for p in pts)/len(pts), len(pts))
    else: print(f,'none')
"

